import json

filepath = "/home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0514-1-projects-struct-self-consist-ie--claude-sessions-agent-c38ec76b/9f896e4f-60e7-40c2-8a85-a71ded9ba959/tool-results/mcp-agent-ml-research-read_registry-1778848076888.txt"

with open(filepath) as f:
    outer = json.load(f)

inner = json.loads(outer["result"])
experiments = inner["data"]["experiments"]

servers = {}
for eid, exp in experiments.items():
    spec = exp.get("spec", {})
    server = spec.get("server", None)
    gpu = spec.get("gpu", None)
    gpu_model = spec.get("gpu_model", None)
    if server:
        key = server
        if key not in servers:
            servers[key] = {"gpus": set(), "gpu_models": set(), "experiments": []}
        if gpu:
            if isinstance(gpu, list):
                for g in gpu:
                    servers[key]["gpus"].add(str(g))
            else:
                servers[key]["gpus"].add(str(gpu))
        if gpu_model:
            servers[key]["gpu_models"].add(str(gpu_model))
        servers[key]["experiments"].append(eid)

for srv, info in sorted(servers.items()):
    gpu_models_str = ", ".join(info["gpu_models"]) if info["gpu_models"] else "not specified"
    print(f"Server: {srv}")
    print(f"  GPUs used: {sorted(info['gpus'])}")
    print(f"  GPU model: {gpu_models_str}")
    print(f"  Experiment count: {len(info['experiments'])}")
    exps_str = ", ".join(info["experiments"][:8])
    if len(info["experiments"]) > 8:
        exps_str += f"... (+{len(info['experiments'])-8} more)"
    print(f"  Experiments: {exps_str}")
    print()

